ru: "Я твердо верю, что каждый ребенок обладает потенциалом, и главная обязанность учителя — помочь им полностью его реализовать.",
de: "Ich glaube fest daran, dass jedes Kind Potenzial hat, und die wichtigste Aufgabe des Lehrers ist es, ihnen zu helfen, dieses voll auszuschöpfen.",
fr: "Je crois fermement que chaque enfant a un potentiel, et le devoir principal de l'enseignant est de l'aider à le réaliser pleinement.",
