ar: "أستمتع بصدق بترجمة المصطلحات المعقدة لأن العثور على مكافئات دقيقة عبر الثقافات يشبه حل لغز مثير للاهتمام.",
fa: "من واقعاً از ترجمه اصطلاحات پیچیده لذت می‌برم زیرا یافتن معادل‌های دقیق میان‌فرهنگی مانند حل کردن یک معما جذاب است.",
"zh-CN": "我由衷地喜欢翻译复杂的习语，因为寻找精准的跨文化对应词就像在解一个有趣的谜题。",
