"it": "Credo fermamente che la medicina non sia solo una professione comune, ma una nobile missione umanitaria dedita a salvare vite umane.",
"tr": "Tıbbın sadece standart bir meslek değil, insan hayatını kurtarmaya adanmış asil bir insani misyon olduğuna yürekten inanıyorum.",
"ar": "أؤمن بشدة أن الطب ليس مجرد مهنة عادية، بل هو رسالة إنسانية نبيلة مكرسة لإنقاذ أرواح البشر.",
"fa": "من قاطعانه باور دارم که پزشکی صرفاً یک شغل معمولی نیست، بلکه یک رسالت شریف و بشردوستانه برای نجات جان انسان‌هاست.",
"zh-CN": "我深信医学不仅仅是一份普通职业，而是一项致力于挽救人类生命的崇高人道主义使命。",
"ja": "医学は単なる標準的な職業ではなく、人命を救うことに捧げられた崇高な人道的使命であると強く信じています。"
