"ru": "Моя главная мотивация — это искреннее стремление облегчать человеческие страдания, излечивать болезни и приносить утешение уязвимым пациентам.",
"de": "Meine Hauptmotivation ist der lebenslange Wunsch, menschliches Leid zu lindern, Krankheiten zu heilen und schutzbedürftigen Patienten echten Trost zu spenden.",
