"ar": "دافعي الرئيسي هو الرغبة الدائمة في تخفيف المعاناة الإنسانية، وعلاج الأمراض، وتقديم مواساة حقيقية للمرضى الضعفاء.",
"fa": "انگیزه اصلی من تمایل همیشگی به کاهش رنج‌های انسان، درمان بیماری‌ها و بخشیدن آرامش واقعی به بیماران آسیب‌پذیر است.",
"zh-CN": "我的主要动力源于终身渴望减轻人类的痛苦、治愈疾病并为脆弱的患者提供真正的慰藉。",
