"ru": "Я проверил прогноз на телефоне. Говорит, что во второй половине дня может пройти небольшой дождь.",
"de": "Ich habe die Vorhersage auf meinem Handy überprüft. Da steht, dass es am Nachmittag leicht regnen könnte.",
"fr": "J'ai vérifié les prévisions sur mon téléphone. Ça dit qu'il pourrait y avoir une petite averse cet après-midi.",
"es": "Revisé el pronóstico en mi teléfono. Dice que podría haber una llovizna por la tarde.",
