"tr": "Telefonumdan hava durumuna baktım. Öğleden sonra hafif bir yağmur olabileceğini söylüyor.",
"ar": "لقد تحققت من توقعات الطقس على هاتفي. تقول إنه قد تكون هناك أمطار خفيفة بعد الظهر.",
"fa": "پیش‌بینی آب و هوا را در گوشی‌ام چک کردم. می‌گوید ممکن است عصر باران ملایمی ببارد.",
"zh-CN": "我用手机查了天气预报。上面说下午可能会有小阵雨。",
"ja": "スマホで天気予報を確認しました。午後には小雨が降るかもしれないって。"
